def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def numbers(text):
    text=re.sub(r'Macro-F1|F1|SHA-256','',text)
    return Counter(re.findall(r'\d+(?:\.\d+)*',text))

def make_draft():
    original=SOURCE.read_text(encoding='utf-8')
    lines=original.splitlines(keepends=True)
    operations=[]
    for prefix,after in EDITS:
        positions=[i for i,line in enumerate(lines) if line.startswith(prefix)]
        assert len(positions)==1,(prefix,positions)
        pos=positions[0]; before=lines[pos].rstrip('\r\n')
        assert numbers(before)==numbers(after),(prefix,'numeric tokens changed',numbers(before)-numbers(after),numbers(after)-numbers(before))
        assert re.findall(r'\[\d+(?:[-,]\d+)*\]',before)==re.findall(r'\[\d+(?:[-,]\d+)*\]',after),prefix
        assert '\n' not in after
        operations.append({'line':pos+1,'before':before,'after':after,
                           'before_sha256':hashlib.sha256(before.encode()).hexdigest(),
                           'after_sha256':hashlib.sha256(after.encode()).hexdigest()})
        lines[pos]=after+'\n'
    result=''.join(lines)
    assert original.split('# 参考文献',1)[1].split('# 附录',1)[0]==result.split('# 参考文献',1)[1].split('# 附录',1)[0]
    assert original.split('## Abstract',1)[1].split('<!--TOC-->',1)[0]==result.split('## Abstract',1)[1].split('<!--TOC-->',1)[0]
    protected=lambda s:[line for line in s.splitlines() if line.startswith(('#','|','![','$$','关键词','副标题'))]
    assert protected(original)==protected(result)
    TARGET.write_text(result,encoding='utf-8',newline='\n')
    QA.mkdir(parents=True,exist_ok=True)
    manifest={'scope':'User seven language rules; Chinese abstract and body prose only',
              'date_Asia_Shanghai':'2026-11-18','source':str(SOURCE),'source_sha256':sha(SOURCE),
              'target':str(TARGET),'target_sha256':sha(TARGET),'operations':operations,
              'numeric_token_multisets_per_paragraph':'UNCHANGED','citations':'UNCHANGED',
              'tables_figures_equations_headings_references':'UNCHANGED','english_abstract':'UNCHANGED',
              'formal_ARS_pipeline_certification':False}
    (QA/'language_revision_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({'paragraphs_edited':len(operations),'source_sha256':sha(SOURCE),'target_sha256':sha(TARGET)},ensure_ascii=False))

def make_docx():
    from docx import Document
    from docx.oxml.ns import qn
    manifest=json.loads((QA/'language_revision_manifest.json').read_text(encoding='utf-8'))
    assert manifest['source_sha256']==sha(SOURCE)
    assert manifest['target_sha256']==sha(TARGET)
    document=Document(DOCX3)
    for op in manifest['operations']:
        matches=[p for p in document.paragraphs if p.text==op['before']]
        assert len(matches)==1,(op['line'],len(matches))
        p=matches[0]
        assert not p._p.xpath('.//w:drawing | .//m:oMath')
        p.clear()
        cursor=0
        for part in re.split(r'(\[\d+(?:[-,]\d+)*\])',op['after']):
            run=p.add_run(part)
            if re.fullmatch(r'\[\d+(?:[-,]\d+)*\]',part):
                run.font.superscript=not op['after'][:cursor].endswith('文献')
            cursor+=len(part)
    document.core_properties.subject='医学人工智能课程论文，语言润色版V4'
    document.save(DOCX4)
    def protected_parts(path):
        from lxml import etree as E
        with ZipFile(path) as archive:
            xml=E.fromstring(archive.read('word/document.xml'))
            ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main','m':'http://schemas.openxmlformats.org/officeDocument/2006/math'}
            return {'equations':[E.tostring(p) for p in xml.findall('.//m:oMath',ns)],
                    'tables':[E.tostring(p) for p in xml.findall('.//w:tbl',ns)],
                    'sections':[E.tostring(p) for p in xml.findall('.//w:sectPr',ns)],
                    'media':{p:hashlib.sha256(archive.read(p)).hexdigest() for p in archive.namelist() if p.startswith('word/media/')}}
    assert protected_parts(DOCX3)==protected_parts(DOCX4),'Protected Word objects changed'
    print(json.dumps({'docx':str(DOCX4),'sha256':sha(DOCX4),'protected_objects':'UNCHANGED'},ensure_ascii=False))

if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--docx',action='store_true')
    args=parser.parse_args()
    if args.docx: make_docx()
    else: make_draft()
